#include <iostream>
#include <type_traits>

template<class T>
constexpr int category() { return std::is_integral_v<T> ? 1 : 0; }
int main() {
    static_assert(category<int>() == 1);
    static_assert(category<double>() == 0);
    std::cout << category<int>() << category<double>() << '\n';
}
